const Travel = () => {
    const [hoveredPlace, setHoveredPlace] = useState(null);

    return (
        <div className="travel">
            <h1>Travel</h1>

            <p className="travel-subtitle">
                Places I've visited
            </p>

            <div className="travel-map">
                <ComposableMap
                    projection="geoMercator"
                    projectionConfig={{
                        center: [78.9629, 22.5937],
                        scale: 1000,
                    }}
                >
                    <Geographies geography={INDIA_MAP}>
                        {({ geographies }) =>
                            geographies.map((geo) => (
                                <Geography
                                    key={geo.rsmKey}
                                    geography={geo}
                                    className="india-map"
                                />
                            ))
                        }
                    </Geographies>

                    {visitedPlaces.map((place) => (
                        <Marker
                            key={place.name}
                            coordinates={place.coordinates}
                        >
                            <circle
                                r={5}
                                className={`travel-marker ${
                                    hoveredPlace === place.name
                                        ? "travel-marker-hover"
                                        : ""
                                }`}
                                onMouseEnter={() =>
                                    setHoveredPlace(place.name)
                                }
                                onMouseLeave={() =>
                                    setHoveredPlace(null)
                                }
                            />

                            {hoveredPlace === place.name && (
                                <text
                                    textAnchor="middle"
                                    y={-12}
                                    className="travel-tooltip"
                                >
                                    {place.name}
                                </text>
                            )}
                        </Marker>
                    ))}
                </ComposableMap>
            </div>
        </div>
    );
};

export default Travel;